const crypto = require('crypto');

const reply = (status, body) => [{ json: { kind: 'respond', status, body } }];
// Ephemeral: only the person who ran the command sees it.
const say = (content) => reply(200, { type: 4, data: { content, flags: 64 } });

// Discord signs timestamp + raw body with the application's Ed25519 key, and
// probes the endpoint with bad signatures, which must get a 401.
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const headers = $input.first().json.headers;
const signature = headers['x-signature-ed25519'] ?? '';
const timestamp = headers['x-signature-timestamp'] ?? '';
const publicKey = $env.DISCORD_PUBLIC_KEY;
if (!publicKey) throw new Error('DISCORD_PUBLIC_KEY is not set');

let valid = false;
try {
  // A raw 32-byte Ed25519 key behind the fixed SPKI prefix.
  const key = crypto.createPublicKey({
    key: Buffer.concat([Buffer.from('302a300506032b6570032100', 'hex'), Buffer.from(publicKey, 'hex')]),
    format: 'der',
    type: 'spki',
  });
  valid = /^[0-9a-f]{128}$/i.test(signature)
    && Math.abs(Date.now() / 1000 - Number(timestamp)) < 300
    && crypto.verify(null, Buffer.concat([Buffer.from(timestamp), raw]), key, Buffer.from(signature, 'hex'));
} catch (e) {
  valid = false;
}
if (!valid) return reply(401, { error: 'invalid request signature' });

const interaction = JSON.parse(raw.toString('utf8'));
if (interaction.type === 1) return reply(200, { type: 1 }); // PING

if ($env.DISCORD_GUILD_ID && interaction.guild_id !== $env.DISCORD_GUILD_ID) return say('This command is not available here.');

const name = interaction.data?.name;
if (![2, 4].includes(interaction.type) || !['tasks', 'add', 'done'].includes(name)) return say('Unknown command.');

const given = interaction.data.options ?? [];
const command = {
  name,
  options: Object.fromEntries(given.map((o) => [o.name, typeof o.value === 'string' ? o.value.trim() : o.value])),
  channel_id: interaction.channel_id,
  application_id: interaction.application_id,
  token: interaction.token,
  // Todoist attributes everything done through the API to the account that
  // connected the credential, so remember who asked.
  who: interaction.member?.nick ?? interaction.member?.user?.global_name ?? interaction.member?.user?.username ?? 'someone',
};

// Type 4: Discord wants suggestions for the option being typed, answered
// directly and within three seconds.
if (interaction.type === 4) return [{ json: { kind: 'autocomplete', command: { ...command, focused: given.find((o) => o.focused)?.name } } }];

// Type 5 shows "thinking..." at once; the result follows as an edit of that
// message, which lifts Discord's three-second limit on the reply. The list is
// public; confirmations of a change are for the caller only, because the relay
// workflow announces the change to the channel anyway.
return [{ json: { kind: 'command', status: 200, body: name === 'tasks' ? { type: 5 } : { type: 5, data: { flags: 64 } }, command } }];

const crypto = require('crypto');

const { kind, command } = $('Verify').first().json;
const { name, options, channel_id, focused } = command;
const wanted = name === 'tasks' ? options.project ?? '' : '';

// Nothing typed into a command may ping anyone.
const fail = (content) => [{
  json: kind === 'autocomplete'
    ? { action: 'no-choices', body: { type: 8, data: { choices: [] } } }
    : { action: 'fail', message: { content, allowed_mentions: { parse: [] } } },
}];
const norm = (s) => s.trim().toLowerCase();

const listed = $('Get projects').first().json;
if (!Array.isArray(listed.results)) {
  return fail(`Could not reach Todoist: ${listed.error?.message ?? 'no project list returned'}. Is the Todoist credential in n8n still connected?`);
}
const projects = listed.results;
const byId = new Map(projects.map((p) => [p.id, p]));
const path = (p) => {
  const names = [];
  for (let q = p; q && names.length < 10; q = byId.get(q.parent_id)) names.unshift(q.name);
  return names.join(' / ');
};

let project;
if (wanted) {
  project = projects.find((p) => norm(p.name) === norm(wanted)) ?? projects.find((p) => norm(path(p)) === norm(wanted));
  if (!project) return fail(`No Todoist project named "${wanted}". Projects: ${projects.map((p) => p.name).join(', ')}`);
} else {
  // A webhook URL answers an unauthenticated GET with the channel it posts to,
  // so the project -> webhook map also says which project this channel is.
  // Autocomplete asks on every keystroke, so the answers are remembered for a
  // day, keyed by a hash because the URL itself is a credential.
  let channels = {};
  try {
    channels = JSON.parse($env.DISCORD_PROJECT_WEBHOOKS || '{}');
  } catch (e) {
    channels = {};
  }
  const cache = $getWorkflowStaticData('global');
  cache.channels ??= {};
  const names = await Promise.all(Object.entries(channels).map(async ([project_name, url]) => {
    const key = crypto.createHash('sha256').update(url).digest('hex');
    let hit = cache.channels[key];
    if (!hit || Date.now() - hit.at > 86400000) {
      try {
        hit = { id: (await this.helpers.httpRequest({ url, json: true, timeout: 8000 })).channel_id, at: Date.now() };
        cache.channels[key] = hit;
      } catch (e) {
        return null;
      }
    }
    return hit.id === channel_id ? project_name : null;
  }));
  const mapped = names.find(Boolean);
  project = mapped && projects.find((p) => norm(p.name) === norm(mapped));
  if (!project) {
    return fail(name === 'tasks'
      ? 'This channel is not mapped to a Todoist project. Try `/tasks project:<name>`.'
      : 'Tasks can only be added or completed from a channel that is mapped to a Todoist project.');
  }
}

return [{
  json: {
    action: kind === 'autocomplete' ? `choices-${focused}` : name,
    project_id: project.id,
    project_name: path(project),
    // Naming the project is redundant in its own channel, but not when it was
    // asked for by name from somewhere else.
    title_prefix: wanted ? `${path(project)}: ` : '',
  },
}];

const { project_id, title_prefix } = $('Pick project').first().json;
const send = (message) => [{ json: { message: { ...message, allowed_mentions: { parse: [] } } } }];

const listed = $('Get tasks (list)').first().json;
if (!Array.isArray(listed.results)) return send({ content: `Could not list tasks: ${listed.error?.message ?? 'no task list returned'}` });
const tasks = listed.results;

// Empty when the lookup failed; tasks then say "assigned" instead of a name.
const people = new Map();
for (const c of $('Get collaborators (list)').first().json.results ?? []) people.set(String(c.id), c.name);

// Soonest due first, undated last, then by priority (4 = p1) and list order.
tasks.sort((a, b) => (a.due?.date ?? '9999').localeCompare(b.due?.date ?? '9999')
  || (b.priority ?? 1) - (a.priority ?? 1)
  || (a.child_order ?? 0) - (b.child_order ?? 0));

const lines = [];
let length = 0;
for (const t of tasks) {
  const text = t.content.length > 150 ? `${t.content.slice(0, 149)}…` : t.content;
  // Content that already holds a markdown link cannot be wrapped in another.
  let line = text.includes('](') ? `• ${text}` : `• [${text}](https://app.todoist.com/app/task/${t.id})`;
  if (t.due) line += ` — ${t.due.string || t.due.date}`;
  if (t.priority > 1) line += ` · p${5 - t.priority}`;
  if (t.responsible_uid) line += ` · ${people.get(String(t.responsible_uid)) ?? 'assigned'}`;
  // An embed description holds 4096 characters.
  if (length + line.length + 1 > 3900) break;
  lines.push(line);
  length += line.length + 1;
}
if (lines.length < tasks.length) lines.push(`…and ${tasks.length - lines.length} more`);

return send({
  embeds: [{
    title: `${title_prefix}${tasks.length} open ${tasks.length === 1 ? 'task' : 'tasks'}`,
    url: `https://app.todoist.com/app/project/${project_id}`,
    description: lines.join('\n') || 'Nothing open.',
    color: 0x3b82f6,
    timestamp: new Date().toISOString(),
  }],
});

const { options, who } = $('Verify').first().json.command;
const { project_id } = $('Pick project').first().json;
const fail = (content) => [{ json: { message: { content, allowed_mentions: { parse: [] } } } }];

const content = (options.task ?? '').trim();
if (!content) return fail('A task needs some text.');

const body = { content: content.slice(0, 500), project_id, description: `Added from Discord by ${who}.` };
if (options.due) body.due_string = options.due;
// The command offers p1-p4; the API counts the other way (4 = p1).
if (options.priority) body.priority = 5 - options.priority;

if (options.assignee) {
  // The value is a collaborator id when picked from the suggestions, or
  // whatever was typed otherwise.
  const people = $('Get collaborators (add)').first().json.results ?? [];
  const typed = String(options.assignee).toLowerCase();
  const person = people.find((c) => String(c.id) === String(options.assignee))
    ?? people.find((c) => c.name.toLowerCase() === typed)
    ?? (people.filter((c) => c.name.toLowerCase().includes(typed)).length === 1 ? people.find((c) => c.name.toLowerCase().includes(typed)) : null);
  if (!person) return fail(`Nobody in this project matches "${options.assignee}". People: ${people.map((c) => c.name).join(', ') || 'none'}`);
  body.assignee_id = person.id;
  return [{ json: { body, assignee: person.name } }];
}
return [{ json: { body } }];

const created = $input.first().json;
const { assignee } = $('Prepare task').first().json;
const send = (content) => [{ json: { message: { content, allowed_mentions: { parse: [] } } } }];

if (!created.id) return send(`Todoist did not accept the task: ${created.error?.message ?? 'no task returned'}`);

let line = `Added [${created.content}](https://app.todoist.com/app/task/${created.id})`;
if (created.due) line += `, due ${created.due.string || created.due.date}`;
if (created.priority > 1) line += `, p${5 - created.priority}`;
if (assignee) line += `, assigned to ${assignee}`;
return send(`${line}.`);

const { options } = $('Verify').first().json.command;
const fail = (content) => [{ json: { message: { content, allowed_mentions: { parse: [] } } } }];

const listed = $('Get tasks (done)').first().json;
if (!Array.isArray(listed.results)) return fail(`Could not list tasks: ${listed.error?.message ?? 'no task list returned'}`);

// The value is a task id when picked from the suggestions, or whatever was
// typed otherwise. Only this project's open tasks can match, so an id from
// anywhere else in the account is refused.
const typed = String(options.task ?? '').toLowerCase();
if (!typed) return fail('Which task?');
const tasks = listed.results;
let matches = tasks.filter((t) => String(t.id).toLowerCase() === typed);
if (!matches.length) matches = tasks.filter((t) => t.content.toLowerCase() === typed);
if (!matches.length) matches = tasks.filter((t) => t.content.toLowerCase().includes(typed));

if (!matches.length) return fail(`No open task here matches "${options.task}".`);
if (matches.length > 1) return fail(`"${options.task}" matches ${matches.length} tasks: ${matches.slice(0, 5).map((t) => t.content).join('; ')}. Pick one from the suggestions.`);
return [{ json: { task_id: matches[0].id, content: matches[0].content, recurring: Boolean(matches[0].due?.is_recurring) } }];

const closed = $input.first().json;
const { content, recurring } = $('Find task').first().json;
const send = (text) => [{ json: { message: { content: text, allowed_mentions: { parse: [] } } } }];

if (closed.error) return send(`Todoist did not complete "${content}": ${closed.error.message ?? 'unknown error'}`);
return send(recurring ? `Completed "${content}"; it recurs, so it moves to its next date.` : `Completed "${content}".`);

const typed = String($('Verify').first().json.command.options.task ?? '').toLowerCase();
const tasks = $input.first().json.results ?? [];

// Discord shows at most 25 suggestions, each up to 100 characters.
const choices = tasks
  .filter((t) => t.content.toLowerCase().includes(typed))
  .sort((a, b) => (a.due?.date ?? '9999').localeCompare(b.due?.date ?? '9999'))
  .slice(0, 25)
  .map((t) => {
    const due = t.due ? ` (${t.due.string || t.due.date})` : '';
    const room = 100 - due.length;
    return { name: (t.content.length > room ? `${t.content.slice(0, room - 1)}…` : t.content) + due, value: String(t.id) };
  });
return [{ json: { body: { type: 8, data: { choices } } } }];

const typed = String($('Verify').first().json.command.options.assignee ?? '').toLowerCase();
const people = $input.first().json.results ?? [];

const choices = people
  .filter((c) => c.name.toLowerCase().includes(typed))
  .slice(0, 25)
  .map((c) => ({ name: c.name.slice(0, 100), value: String(c.id) }));
return [{ json: { body: { type: 8, data: { choices } } } }];
